<?php $pageTitle='Issue / Return';require __DIR__.'/config/database.php';require __DIR__.'/includes/header.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','librarian']);$a=$_POST['action'];if($a==='issue'){$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT * FROM books WHERE id=? FOR UPDATE");$s->execute([(int)$_POST['book_id']]);$b=$s->fetch();$s=$pdo->prepare("SELECT * FROM members WHERE id=?");$s->execute([(int)$_POST['member_id']]);$m=$s->fetch();if(!$b||$b['available_copies']<1||!$m||$m['status']!=='active')throw new Exception('Book unavailable or member inactive.');$days=(int)$pdo->query("SELECT setting_value FROM settings WHERE setting_key='loan_days'")->fetchColumn();$s=$pdo->prepare("INSERT INTO loans(book_id,member_id,issued_by,issue_date,due_date) VALUES(?,?,?,CURDATE(),DATE_ADD(CURDATE(),INTERVAL ? DAY))");$s->execute([$b['id'],$m['id'],$_SESSION['user_id'],$days]);$pdo->prepare("UPDATE books SET available_copies=available_copies-1 WHERE id=?")->execute([$b['id']]);$pdo->commit();$msg='Book issued successfully.';}catch(Throwable $e){$pdo->rollBack();$msg=$e->getMessage();}}else{$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT * FROM loans WHERE id=? AND status='issued' FOR UPDATE");$s->execute([(int)$_POST['loan_id']]);$l=$s->fetch();if(!$l)throw new Exception('Active loan not found.');$rate=(float)$pdo->query("SELECT setting_value FROM settings WHERE setting_key='fine_per_day'")->fetchColumn();$days=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($l['due_date']))/86400));$pdo->prepare("UPDATE loans SET return_date=CURDATE(),fine_amount=?,status='returned' WHERE id=?")->execute([$days*$rate,$l['id']]);$pdo->prepare("UPDATE books SET available_copies=available_copies+1 WHERE id=?")->execute([$l['book_id']]);$pdo->commit();$msg='Returned. Fine: ₹'.number_format($days*$rate,2);}catch(Throwable $e){$pdo->rollBack();$msg=$e->getMessage();}}}$books=$pdo->query("SELECT id,title,accession_no FROM books WHERE available_copies>0 AND status='active'")->fetchAll();$members=$pdo->query("SELECT id,member_code,name FROM members WHERE status='active'")->fetchAll();$loans=$pdo->query("SELECT l.id,l.due_date,b.title,m.member_code FROM loans l JOIN books b ON b.id=l.book_id JOIN members m ON m.id=l.member_id WHERE l.status='issued' ORDER BY l.due_date")->fetchAll();?><h2>Issue / Return</h2><?php if($msg):?><div class="alert alert-info"><?=h($msg)?></div><?php endif;?><div class="row"><div class="col-md-5"><div class="card card-body"><h5>Issue Book</h5><form method="post"><input type="hidden" name="action" value="issue"><select class="form-select mb-3" name="book_id" required><option value="">Select book</option><?php foreach($books as $b):?><option value="<?=$b['id']?>"><?=h($b['title'].' - '.$b['accession_no'])?></option><?php endforeach;?></select><select class="form-select mb-3" name="member_id" required><option value="">Select member</option><?php foreach($members as $m):?><option value="<?=$m['id']?>"><?=h($m['member_code'].' - '.$m['name'])?></option><?php endforeach;?></select><button class="btn btn-primary">Issue</button></form></div></div><div class="col-md-7"><div class="card card-body"><h5>Active Loans</h5><table class="table"><tr><th>Member</th><th>Book</th><th>Due</th><th></th></tr><?php foreach($loans as $l):?><tr><td><?=h($l['member_code'])?></td><td><?=h($l['title'])?></td><td><?=h($l['due_date'])?></td><td><form method="post"><input type="hidden" name="action" value="return"><input type="hidden" name="loan_id" value="<?=$l['id']?>"><button class="btn btn-sm btn-success">Return</button></form></td></tr><?php endforeach;?></table></div></div></div><?php require __DIR__.'/includes/footer.php';